  const loop = (t) => {
    renderer.resize();
    renderer.render(t * 0.001);
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
}

boot();

/** PBR math helpers. Incomplete / buggy on purpose. */
